class Solution:
    def camelMatch(self, queries: list[str], pattern: str) -> list[bool]:
        def matches(query: str) -> bool:
            p = 0
            for ch in query:
                if p < len(pattern) and ch == pattern[p]:
                    p += 1
                elif ch.isupper():
                    return False
            return p == len(pattern)

        return [matches(q) for q in queries]

class Solution {
public:
    vector<bool> camelMatch(vector<string>& queries, string pattern) {
        auto matches = [&](const string& query) -> bool {
            int p = 0;
            for (char ch : query) {
                if (p < (int)pattern.size() && ch == pattern[p]) {
                    p++;
                } else if (isupper(ch)) {
                    return false;
                }
            }
            return p == (int)pattern.size();
        };

        vector<bool> res;
        res.reserve(queries.size());
        for (const string& q : queries) {
            res.push_back(matches(q));
        }
        return res;
    }
};

class Solution {
    public List<Boolean> camelMatch(String[] queries, String pattern) {
        List<Boolean> res = new ArrayList<>(queries.length);
        for (String q : queries) {
            res.add(matches(q, pattern));
        }
        return res;
    }

    private boolean matches(String query, String pattern) {
        int p = 0;
        for (int i = 0; i < query.length(); ++i) {
            char ch = query.charAt(i);
            if (p < pattern.length() && ch == pattern.charAt(p)) {
                p++;
            } else if (Character.isUpperCase(ch)) {
                return false;
            }
        }
        return p == pattern.length();
    }
}

var camelMatch = function(queries, pattern) {
    const matches = (query) => {
        let p = 0;
        for (let i = 0; i < query.length; i++) {
            const ch = query[i];
            if (p < pattern.length && ch === pattern[p]) {
                p++;
            } else if (ch >= 'A' && ch <= 'Z') {
                return false;
            }
        }
        return p === pattern.length;
    };
    return queries.map(matches);
};
